    proof.verifiedAt = this.now();
    let result: GraphRecoveryResult;
    if (prior) {
      if (canonical(prior.decision) !== canonical(decision)) fail("DECISION_CONFLICT");
      result = this.verified(connection, registration, snapshot, proof, () => this.store.verifyDecision(snapshot, request.receiptId, proof, this.now()));
